styles.cssStarter:
:root{--accent:#f07a12;--bg:#0a0a0a;--surface:#141414;--surface-2:#1c1c1c;--ink:#ffffff;--muted:#b9b4ac;--line:rgba(255,255,255,.12);--container:1280px;--gutter:32px;--section-y:120px;--radius:16px}
body{background:var(--bg);color:var(--muted);font-family:'Inter',sans-serif;font-size:16px;line-height:1.7}
.container{max-width:var(--container);padding:0 var(--gutter);margin:0 auto}
section{padding:var(--section-y) 0}
h1,h2,h3{font-family:'Playfair Display',serif;color:var(--ink);font-weight:500}
h1{font-size:76px;line-height:1.05;letter-spacing:-1.5px}
h1 em,h2 em{font-style:italic;color:var(--accent)}
h2{font-size:52px;line-height:1.1;letter-spacing:-.5px}
h3{font-size:24px;line-height:1.3}
.eyebrow{font-size:13px;letter-spacing:.18em;text-transform:uppercase;color:var(--accent)}
.lead{font-size:18px;max-width:520px}
.btn{display:inline-flex;align-items:center;gap:12px;min-height:48px;padding:6px 6px 6px 22px;border-radius:999px;background:var(--accent);color:#111;font-weight:500}
.btn .arrow{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;background:#111;color:#fff}
.card{background:var(--surface);border-radius:var(--radius);border:1px solid var(--line)}
@media(max-width:768px){:root{--section-y:72px;--gutter:20px}h1{font-size:44px}h2{font-size:34px}}

:root{--accent:#8e0f0f;--accent-2:#6f0a0a;--cream:#f4ece0;--dark:#120d0c;--ink:#1a1110;--muted:#6e625c;--line:rgba(26,17,16,.14);--container:1280px;--gutter:32px;--section-y:96px}
body{background:var(--cream);color:var(--muted);font-family:'Jost',sans-serif;font-size:15px;line-height:1.7;font-weight:300}
.container{max-width:var(--container);padding:0 var(--gutter);margin:0 auto}
section{padding:var(--section-y) 0}
h1,h2,h3{font-family:'Cormorant Garamond',serif;font-weight:500;text-transform:uppercase;letter-spacing:-.01em;color:var(--ink)}
.on-red h1,.on-red h2,.on-dark h1,.on-dark h2{color:#fff}
h1{font-size:72px;line-height:.98}
h2{font-size:54px;line-height:1}
h3{font-size:22px;line-height:1.15}
.eyebrow{font-size:11px;letter-spacing:.22em;text-transform:uppercase;font-weight:500;color:var(--accent);margin-bottom:12px}
.btn{display:inline-flex;align-items:center;gap:8px;min-height:44px;padding:0 20px;background:var(--accent);color:#fff;font-size:12px;letter-spacing:.14em;text-transform:uppercase;border-radius:0}
.link-arrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;text-decoration:none;border-bottom:1px solid currentColor}
.band-red{background:var(--accent);color:#f3dcd6}
.band-dark{background:var(--dark);color:#cfc6bf}
@media(max-width:768px){:root{--section-y:64px;--gutter:20px}h1{font-size:44px}h2{font-size:36px}}

:root{--accent:#c2402d;--bg:#fbf3e4;--paper:#fffaf1;--ink:#2a120c;--muted:#6b5a52;--dark:#241310;--line:#e6d7bf;--container:1280px;--gutter:32px;--section-y:112px;--radius:18px}
body{background:var(--bg);color:var(--muted);font-family:'DM Sans',sans-serif;font-size:16px;line-height:1.65}
.container{max-width:var(--container);padding:0 var(--gutter);margin:0 auto}
section{padding:var(--section-y) 0}
h1,h2,h3{font-family:'Instrument Serif',serif;font-weight:400;color:var(--ink)}
h1{font-size:88px;line-height:1;letter-spacing:-1.5px}
h2{font-size:56px;line-height:1.05;letter-spacing:-.8px}
h3{font-size:28px;line-height:1.15}
h1 em,h2 em{font-style:italic;color:var(--accent)}
.chip{display:inline-block;padding:5px 14px;border:1px solid var(--ink);border-radius:999px;font-size:13px;color:var(--ink);margin-bottom:18px}
.btn{display:inline-flex;align-items:center;min-height:46px;padding:0 24px;border-radius:999px;background:var(--accent);color:#fff;font-size:13px;font-weight:600;letter-spacing:.06em;text-transform:uppercase}
.card{background:var(--paper);border:1px solid var(--line);border-radius:var(--radius)}
.band-dark{background:var(--dark);color:#e9dccb}
@media(max-width:768px){:root{--section-y:72px;--gutter:20px}h1{font-size:52px}h2{font-size:38px}}

:root{--accent:#d62b2b;--green:#1f4d3a;--yellow:#f5c542;--cream:#fdf5e4;--ink:#16120f;--muted:#4d4640;--container:1280px;--gutter:32px;--section-y:104px;--radius:24px}
body{background:var(--cream);color:var(--muted);font-family:'Inter',sans-serif;font-size:16px;line-height:1.6}
.container{max-width:var(--container);padding:0 var(--gutter);margin:0 auto}
section{padding:var(--section-y) 0}
h1,h2,h3{font-family:'Bricolage Grotesque',sans-serif;font-weight:800;color:var(--ink);text-transform:uppercase;letter-spacing:-.02em}
h1{font-size:112px;line-height:.9}
h2{font-size:60px;line-height:.95}
h3{font-size:24px;line-height:1.1}
.eyebrow{font-weight:600;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:var(--accent)}
.btn{display:inline-flex;align-items:center;gap:10px;min-height:50px;padding:0 26px;border-radius:999px;background:var(--ink);color:#fff;font-weight:700;text-transform:uppercase;letter-spacing:.04em;border:2px solid var(--ink)}
.btn-accent{background:var(--accent);border-color:var(--accent)}
.sticker{display:grid;place-items:center;width:110px;height:110px;border-radius:50%;background:var(--yellow);color:var(--ink);font-weight:800;text-transform:uppercase;font-size:12px;transform:rotate(-12deg)}
.marquee{overflow:hidden;background:var(--yellow);border-block:2px solid var(--ink)}
.card{background:#fff;border:2px solid var(--ink);border-radius:var(--radius)}
@media(max-width:768px){:root{--section-y:64px;--gutter:20px}h1{font-size:60px}h2{font-size:38px}}
